class Siege extends Base{
 constructor(difficulty,saved,options={}){super(difficulty,saved,options);this.s.siegeVersion=1;if(!saved){for(const bank of this.s.resources)Object.assign(bank,{food:260,wood:400,gold:120,stone:150});this.enrichWorld()}this.s.fortress??=null;for(const t of this.s.tech)for(const key of ['aeronautics','forgefire','runeward','aetherlattice'])t[key]??=0}
 air(u){return D[u?.kind]?.domain==='air'}
 enrichWorld(){const s=this.s,w=this.world,W=w.width,H=w.height;for(const l of [{x:W*.21,y:H*.48,rx:170,ry:100},{x:W*.79,y:H*.48,rx:170,ry:100}])if(!w.starts.some(p=>dist(p,l)<850)&&dist(l,w.objective)>900)w.lakes.push(l);this.grid=this.seaGrid=null;for(let i=0;i<(w.size==='large'?50:30);i++){const x=this.rand(180,W-180),y=this.rand(180,H-180);if(w.starts.some(p=>dist(p,{x,y})<850)||dist({x,y},w.objective)<800)continue;for(let j=0;j<10;j++){const px=x+this.rand(-110,110),py=y+this.rand(-110,110);if(!this.blocked(px,py)&&!s.buildings.some(b=>dist(b,{x:px,y:py})<110))this.node('wood',px,py,420,'forest')}}this.updateFog()}
 gatherRate(u,n){return super.gatherRate(u,n)*.75}
 builder(u){return u?.kind==='siegewagon'||super.builder(u)}
 sight(e){return this.air(e)?(e.kind==='scoutballoon'?780:520):super.sight(e)}
 sightBlocked(a,b){return this.air(a)?false:super.sightBlocked(a,b)}
 blocked(x,y,u=null){if(!this.world)return super.blocked(x,y,u);if(!K.worldPlayable(this.world,x,y))return true;if(this.air(u))return false;if(this.sea(u)?!K.worldWater(this.world,x,y):K.worldWater(this.world,x,y)||K.worldRocky(this.world,x,y))return true;return this.s.buildings.some(b=>{if(b.hp<=0)return false;const d=D[b.kind];if(d.gate&&u&&this.allied(u.team,b.team))return false;if(d.wall){const rx=d.vertical?20:48,ry=d.vertical?48:20;return Math.abs(x-b.x)<rx+9&&Math.abs(y-b.y)<ry+9}return dist(b,{x,y})<d.r+(this.sea(u)?12:9)})}
 getGrid(u=null){if(!this.world||this.sea(u)||!this.s.buildings.some(b=>D[b.kind].gate))return super.getGrid(u);if(!this.grid){this._gateGrids=new Map();this.grid={gates:true}}const key=u?.team??-2;this._gateGrids??=new Map();if(this._gateGrids.has(key))return this._gateGrids.get(key);const cols=M.width/48,rows=M.height/48,g=new Uint8Array(cols*rows);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)g[y*cols+x]=this.blocked(x*48+24,y*48+24,u)?1:0;this._gateGrids.set(key,g);return g}
 freeSpawn(u){if(!this.air(u))return super.freeSpawn(u);if(this.blocked(u.x,u.y,u)){const town=this.s.buildings.find(b=>b.team===u.team&&b.kind==='town')||this.world?.starts[u.team];if(town){u.x=town.x;u.y=town.y}}}
 findPath(u,x,y){if(!this.air(u))return super.findPath(u,x,y);if(!K.worldPlayable(this.world,x,y))return [];return[{x,y}]}
 walk(u,p,stop,dt){if(!this.air(u)){if(D[p.kind]?.wall&&dist(u,p)>stop){const dx=u.x-p.x,dy=u.y-p.y,d=Math.hypot(dx,dy),r=Math.max(60,stop-4);return super.walk(u,{x:p.x+dx/d*r,y:p.y+dy/d*r},4,dt)}return super.walk(u,p,stop,dt)}const dx=p.x-u.x,dy=p.y-u.y,d=Math.hypot(dx,dy);if(d<=stop){u.path=[];return true}if(!K.worldPlayable(this.world,p.x,p.y))return false;const step=Math.min(d-stop,this.stat(u,'speed')*dt);u.x+=dx/d*step;u.y+=dy/d*step;u.facing=dx>=0?1:-1;u.path=[{x:p.x,y:p.y}];return step>=d-stop}
 antiAir(u){return D[u.kind].monster||D[u.kind].antiAir||['archer','skirmisher','musketeer'].includes(D[u.kind].role)||u.kind==='tower'}
 canTarget(u,e){if(this.air(e)&&!this.antiAir(u))return false;return super.canTarget(u,e)}
 damage(e,amount,source){if(source&&this.air(e)&&!this.antiAir(source))return;if(source?.kind==='trebuchet'&&D[e.kind].building)amount*=2.5;super.damage(e,amount,source)}
 stat(e,key){let v=super.stat(e,key);const t=this.s.tech[e.team]||{};if(key==='hp'&&this.air(e)&&t.aetherlattice)v=Math.round(v*1.1);if(key==='armor'&&D[e.kind].hero&&t.runeward)v+=2;return v}
 placementError(kind,x,y,team=0){if(kind==='kcreclaimed')return '远征要塞只能通过击败守卫占领';if(!D[kind]?.wall)return super.placementError(kind,x,y,team);const d=D[kind],w=this.world;if(d.age>this.s.ages[team])return '需要 '+K.ageNames[d.age];if(!this.canPay(d,team))return '资源不足';if(!this.canSee(team,{x,y}))return '先探索并照亮施工区域';for(const dx of [-45,0,45])for(const dy of [-20,0,20]){const p=d.vertical?{x:x+dy,y:y+dx}:{x:x+dx,y:y+dy};if(!K.worldPlayable(w,p.x,p.y)||K.worldWater(w,p.x,p.y)||K.worldRocky(w,p.x,p.y))return '城墙需要可通行陆地'}if(dist({x,y},w.objective)<430)return 'KC 要塞周围无法建造';if(this.s.nodes.some(n=>dist(n,{x,y})<55))return '需要远离建筑和资源';if(this.s.buildings.some(b=>{const a=D[b.kind];return a.wall?Math.abs(x-b.x)<(a.vertical?28:85)&&Math.abs(y-b.y)<(a.vertical?85:28):dist(b,{x,y})<a.r+65}))return '城墙或建筑位置重叠';if(!this.s.buildings.some(b=>b.team===team&&b.complete&&dist(b,{x,y})<650)&&!this.s.units.some(u=>u.team===team&&this.builder(u)&&dist(u,{x,y})<180))return '先派村民或工程师到附近';return ''}
 unitError(b,kind){if(this.air({kind})&&!this.s.tech[b?.team||0].aeronautics)return '先研究航空工程';if(kind==='emberthrower'&&!this.s.tech[b?.team||0].forgefire)return '先研究 KC 符文熔炉';const cap={gunship:2,airtransport:3,scoutballoon:3,runesentinel:8,emberthrower:4}[kind];if(cap){const team=b?.team||0,count=this.s.units.filter(u=>u.team===team&&u.kind===kind).length+this.s.buildings.filter(b=>b.team===team).reduce((n,b)=>n+b.queue.filter(q=>q.kind===kind).length,0);if(count>=cap)return '本兵种已达数量上限 '+cap}return super.unitError(b,kind)}
 board(ship){if(!this.air(ship)&&ship.kind!=='transport')return super.board(ship);if(!D[ship.kind].transport&&ship.kind!=='transport')return '请选择运输飞艇';const cap=D[ship.kind].cargoCapacity||6,loaded=this.s.units.filter(u=>u.embarkedOn===ship.id);let used=loaded.reduce((n,u)=>n+(D[u.kind].pop||1),0),count=0;for(const u of this.s.units.filter(u=>u.id!==ship.id&&u.team===ship.team&&!this.air(u)&&!this.sea(u)&&!u.embarkedOn&&dist(u,ship)<140)){if(used+(D[u.kind].pop||1)>cap)continue;u.embarkedOn=ship.id;u.path=[];u.order=null;used+=D[u.kind].pop||1;count++}ship.cargo=this.s.units.filter(u=>u.embarkedOn===ship.id).map(u=>u.id);return count?'已装载 '+count+' 名单位（'+used+'/'+cap+' 人口）':'让陆军靠近飞艇后再装载'}
 unload(ship){if(!this.air(ship))return super.unload(ship);if(K.worldWater(this.world,ship.x,ship.y)||K.worldRocky(this.world,ship.x,ship.y))return '飞艇必须在可通行陆地上空卸载';if(this.s.units.some(u=>this.hostile(ship.team,u.team)&&u.hp>0&&!u.embarkedOn&&dist(ship,u)<150))return '附近有敌军，无法安全卸载';return super.unload(ship)}
 tick(dt){if(this.s.ended)return;const s=this.s;if(s.lair&&!s.lair.cleared&&!s.lair.guards.some(id=>this.byId(id)?.hp>0)){const lair=this.byId(s.lair.id);if(lair)lair.hp=0}super.tick(dt);if(s.ended)return;if(s.lair?.cleared&&!s.fortress){const best=Math.max(...s.lair.contribution);if(best>0){const owner=s.lair.contribution.indexOf(best),p=this.world.objective,b=this.add('kcreclaimed',owner,p.x,p.y);b.hp=b.maxhp*.7;s.fortress={owner,id:b.id};this.grid=this.seaGrid=null;this.emit('fortressCaptured',{team:owner,text:'KC 要塞已占领，可生产独有兵种与研发科技'})}}for(const u of s.units){if(D[u.kind].hero&&s.tech[u.team].runeward)u.mana=Math.min(s.loot[u.team]?.chosen==='book'?100:80,(u.mana||0)+dt*.2);if(u.kind==='siegewagon'&&!u.embarkedOn){const b=this.nearest(u,s.buildings.filter(b=>b.team===u.team&&b.complete&&b.hp<b.maxhp&&dist(b,u)<150&&s.time-(b.lastHurtAt||0)>5));if(b)b.hp=Math.min(b.maxhp,b.hp+dt*7)}}}
 raids(){super.raids();this._breachAt??={};for(let team=1;team<this.s.nations.length;team++){if(this.s.time<(this._breachAt[team]||0))continue;this._breachAt[team]=this.s.time+15;const army=this.s.units.filter(u=>u.team===team&&u.order?.type==='advance'&&D[u.kind].damage>0&&!u.embarkedOn);if(army.length<2)continue;const known=this.view(team).buildings.filter(b=>D[b.kind]?.wall&&this.hostile(team,b.team)&&this.canSee(team,b));if(!known.length)continue;const lead=army[0],goal=lead.order;if(this.findPath(lead,goal.x,goal.y).length)continue;const wall=this.nearest(lead,known);this.order(army,{type:'attack',id:wall.id})}}
 aiPlayer(team){super.aiPlayer(team);const age=this.s.ages[team],town=this.s.buildings.find(b=>b.team===team&&b.kind==='town'),worker=this.s.units.find(u=>u.team===team&&this.builder(u));if(!town||!worker)return;const plans=age>=5?['siegeyard','aerodrome']:age>=3?['siegeyard']:[],kind=plans.find(k=>!this.s.buildings.some(b=>b.team===team&&b.kind===k));if(kind&&!this.s.buildings.some(b=>b.team===team&&!b.complete))for(let i=0;i<12;i++){const x=town.x+this.rand(-450,450),y=town.y+this.rand(-400,400);if(!this.placementError(kind,x,y,team)){this.construct(kind,x,y,[worker],team);break}}}
}
